import{_ as a,a as e}from"./chunks/ind-public-data-structure.Bk53oDPn.js";import{_ as o}from"./chunks/ind-public-chart.BeYuNPiS.js";import{_ as r,o as s,c as n,ag as i}from"./chunks/framework.CxkNbRKf.js";const d="/nada-documentation/images/ind-public-table.png",l="/nada-documentation/images/ind-public-data-api.png",A=JSON.parse('{"title":"Indicators — Catalog frontend","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/content/indicators-frontend.md","filePath":"admin-guide/content/indicators-frontend.md","lastUpdated":1793155456000}'),h={name:"admin-guide/content/indicators-frontend.md"};function c(p,t,g,u,m,f){return s(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="indicators-—-catalog-frontend" tabindex="-1">Indicators — Catalog frontend <a class="header-anchor" href="#indicators-—-catalog-frontend" aria-label="Permalink to &quot;Indicators — Catalog frontend&quot;">​</a></h1><p>Also see the <a href="./indicators.html">overview</a> and <a href="./indicators-admin.html">Create an indicator in NADA</a>.</p><p>A published indicator has its own page in the catalog. The screenshots show the sample indicator SI.POV.DDAY from the <a href="./indicators-tutorial.html">tutorial</a>.</p><p>The page header shows the thumbnail, the title, the countries and years covered (for example <em>Angola, Albania, Argentina...and 180 more, 1963 - 2025</em>), the <strong>Reference ID</strong>, and a link to download the metadata as <strong>JSON</strong>.</p><p>The page has five tabs.</p><div class="info custom-block"><p class="custom-block-title">Tabs depend on the data</p><p>The <strong>Data structure</strong> tab appears when the indicator has a data structure. <strong>Chart &amp; data</strong>, <strong>Table</strong> and <strong>Data API</strong> also need its data, and are hidden while the indicator is out of sync. A <strong>Downloads</strong> tab appears when resources, such as documents or links, are attached to the indicator.</p></div><hr><h2 id="series-description" tabindex="-1">Series description <a class="header-anchor" href="#series-description" aria-label="Permalink to &quot;Series description&quot;">​</a></h2><p>The default tab. It shows the indicator&#39;s metadata, organized into sections listed on the left, such as <strong>overview</strong>, <strong>Data structure</strong>, <strong>Geographic information</strong>, <strong>License</strong> and <strong>Metadata production</strong>. Which sections appear depends on the metadata entered.</p><p><img src="'+a+'" alt="Series description"></p><hr><h2 id="chart-data" tabindex="-1">Chart &amp; data <a class="header-anchor" href="#chart-data" aria-label="Permalink to &quot;Chart &amp; data&quot;">​</a></h2><p>An interactive chart of the indicator&#39;s data.</p><ul><li>On the left, a filter for each coded column: a <strong>Year</strong> slider and, for the sample, a <strong>Country</strong> list with a search box. The first code is selected at first. The chart updates as soon as you change a filter.</li><li>Above the chart, choose the chart type: <strong>Auto</strong>, <strong>Line</strong>, <strong>Columns</strong> or <strong>Bars</strong>.</li><li>The chart title, subtitle (years and selected countries) and <strong>Source</strong> are added automatically.</li><li><strong>Chart data</strong>, below the chart, lists the values shown, with the number of rows.</li></ul><p><img src="'+o+'" alt="Chart &amp; data, Albania and Argentina"></p><div class="tip custom-block"><p class="custom-block-title">Filters follow you between tabs</p><p>The filters you choose on <strong>Chart &amp; data</strong> are kept when you open <strong>Table</strong>, and the other way round. They are also part of the page address, so a copied link opens with the same selection.</p></div><hr><h2 id="table" tabindex="-1">Table <a class="header-anchor" href="#table" aria-label="Permalink to &quot;Table&quot;">​</a></h2><p>The same data as a table, for example with countries as rows and years as columns. <strong>Filters</strong> shows the filters, which update the table as soon as you change them; <strong>Layout</strong> changes the rows and columns, and <strong>Full window</strong> enlarges the table.</p><p><img src="'+d+'" alt="Table"></p><hr><h2 id="data-api" tabindex="-1">Data API <a class="header-anchor" href="#data-api" aria-label="Permalink to &quot;Data API&quot;">​</a></h2><p>How to get the data programmatically:</p><ul><li>a short description of the indicator;</li><li><strong>API usage</strong>: example calls and their parameters;</li><li><strong>Data explorer</strong>: all observations, with paging.</li></ul><p>For the endpoints and parameters, see <a href="./indicators-data-api.html">Indicator data API</a>.</p><p><img src="'+l+'" alt="Data API"></p><hr><h2 id="data-structure" tabindex="-1">Data structure <a class="header-anchor" href="#data-structure" aria-label="Permalink to &quot;Data structure&quot;">​</a></h2><p>The columns of the data, so that users understand them before using the data:</p><ul><li><strong>Name</strong>: the column name used in the data and the API.</li><li><strong>Label</strong>: a readable description.</li><li><strong>Role</strong>: shown as a badge, such as <code>INDICATOR_ID</code>, <code>GEOGRAPHY</code>, <code>TIME_PERIOD</code> or <code>OBSERVATION_VALUE</code>.</li><li><strong>Type</strong>: the data type.</li><li><strong>Codelist</strong>: for coded columns. Expand the row to see and search the codes.</li></ul><p><strong>Download JSON</strong> and <strong>Download SDMX/XML</strong> download the data structure.</p><p><img src="'+e+'" alt="Data structure, REF_AREA expanded"></p>',32)])])}const T=r(h,[["render",c]]);export{A as __pageData,T as default};
